275:       - name: Start AgentsWeb SSH session
276:         id: agentsweb
277:         timeout-minutes: 5
278:         if: env.TEST_REQUEST != 'true' && env.AGENTSWEB_SSH_ENABLED == 'true'
279:         continue-on-error: true
280:         shell: bash
281:         run: |
282:           set -euo pipefail
283:           # GITHUB_RUN_NUMBER starts at 1 in every repository, so using it here
284:           # makes every new repository's first OMG run contend for port 32001.
285:           # GITHUB_RUN_ID is globally unique and distributes runs across the
286:           # broker's 32000-32999 public-port range.
287:           REQUESTED_SSH_PORT=$((32000 + GITHUB_RUN_ID % 1000))
288:           # Reuse the runner's sshd without touching apt or preview dependencies.
289:           if [[ "$RUNNER_OS" == 'Linux' && ! -x /usr/sbin/sshd ]]; then
290:             /usr/bin/time -p timeout --kill-after=10s 90s sudo -n apt-get \
291:               -o Acquire::ForceIPv4=true -o Acquire::Retries=1 \
292:               -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 update
293:             /usr/bin/time -p timeout --kill-after=10s 90s sudo -n apt-get \
294:               -o Acquire::ForceIPv4=true -o Acquire::Retries=1 \
295:               -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 install -y openssh-server
296:           fi
297:           /usr/bin/time -p test -x /usr/sbin/sshd
298:           install -d -m 700 "$SSH_DIR"
299:           SSH_KEY="$RUNNER_TEMP/opencode-agentsweb-id_ed25519"
300:           SSH_PUBLIC_KEY="$SSH_KEY.pub"
301:           printf 'SSH_KEY=%s\nSSH_PUBLIC_KEY=%s\n' "$SSH_KEY" "$SSH_PUBLIC_KEY" >> "$GITHUB_ENV"
302:           ssh-keygen -t ed25519 -f "$SSH_KEY" -N '' -q
303:           chmod 600 "$SSH_KEY"
304:           install -d -m 700 "$HOME/.ssh"
305:           {
306:             cat "$SSH_PUBLIC_KEY"
307:             printf '%s\n' "$AGENTSWEB_SSH_PUBLIC_KEY"
308:           } > "$HOME/.ssh/authorized_keys"
309:           chmod 600 "$HOME/.ssh/authorized_keys"
310:           [[ "$RUNNER_OS" != 'Linux' ]] || sudo mkdir -p /run/sshd
311:           # shellcheck disable=SC2024
312:           sudo /usr/sbin/sshd -D -e -p 2222 \
313:             -o PasswordAuthentication=no -o PermitRootLogin=no \
314:             -o PubkeyAuthentication=yes > "$SSH_DIR/sshd.log" 2>&1 &
315:           echo $! > "$SSH_DIR/sshd.pid"
316:           is_listening() {
317:             if [[ "$RUNNER_OS" == 'macOS' ]]; then
318:               if command -v nc >/dev/null 2>&1 && nc -z -w 1 127.0.0.1 2222 >/dev/null 2>&1; then
319:                 return 0
320:               fi
321:               command -v lsof >/dev/null 2>&1 && sudo lsof -nP -a -iTCP:2222 -sTCP:LISTEN >/dev/null 2>&1
322:             elif command -v ss >/dev/null 2>&1; then
323:               ss -ltn | grep -q ':2222 '
324:             elif command -v lsof >/dev/null 2>&1; then
325:               lsof -nP -a -iTCP:2222 -sTCP:LISTEN >/dev/null 2>&1
326:             else
327:               nc -z 127.0.0.1 2222 >/dev/null 2>&1
328:             fi
329:           }
330:           for _ in {1..120}; do
331:             if is_listening; then
332:               break
333:             fi
334:             if ! kill -0 "$(cat "$SSH_DIR/sshd.pid")" 2>/dev/null; then
335:               echo 'Local sshd exited before listening on port 2222.' >&2
336:               sed -n '1,160p' "$SSH_DIR/sshd.log" >&2
337:               exit 1
338:             fi
339:             sleep 1
340:           done
341:           if ! is_listening; then
342:             echo 'Local sshd did not start listening on port 2222.' >&2
343:             sed -n '1,160p' "$SSH_DIR/sshd.log" >&2
344:             exit 1
345:           fi
346:           nohup env PYTHONPATH="$AGENTSWEB_DIR" \
347:             python3 -m lolgames_tunnel client 127.0.0.1:2222 \
348:             --server agentsweb.space --name "$SSH_NAME" --public-port "$REQUESTED_SSH_PORT" \
349:             > "$SSH_DIR/tunnel.log" 2>&1 &
350:           echo $! > "$SSH_DIR/tunnel.pid"
351:           for _ in {1..45}; do
352:             grep -q '^ssh://' "$SSH_DIR/tunnel.log" && break
353:             if ! kill -0 "$(cat "$SSH_DIR/tunnel.pid")" 2>/dev/null; then
354:               break
355:             fi
356:             sleep 1
357:           done
358:           if ! grep -q '^ssh://' "$SSH_DIR/tunnel.log"; then
359:             echo 'AgentsWeb tunnel did not register.' >&2
360:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
361:             exit 1
362:           fi
363:           SSH_TUNNEL_URL="$(sed -n 's#^\(ssh://[^[:space:]]*\).*#\1#p' "$SSH_DIR/tunnel.log" | head -n 1)"
364:           endpoint="$(sed -nE 's#^ssh://([^:[:space:]]+):([0-9]+).*$#\1 \2#p' "$SSH_DIR/tunnel.log" | head -n 1)"
365:           if [[ -z "$endpoint" ]]; then
366:             echo 'AgentsWeb tunnel registration did not contain a usable SSH endpoint.' >&2
367:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
368:             exit 1
369:           fi
370:           read -r SSH_HOST SSH_PORT <<<"$endpoint"
371:           [[ -n "$SSH_HOST" && "$SSH_PORT" =~ ^[0-9]+$ ]]
372:           SSH_COMMAND="ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -i ~/.ssh/aiplay-agentsweb -p ${SSH_PORT} runner@${SSH_HOST}"
373:           {
374:             printf 'AGENTSWEB_HOST=%s\n' "$SSH_HOST"
375:             printf 'AGENTSWEB_PORT=%s\n' "$SSH_PORT"
376:             printf 'AGENTSWEB_COMMAND=%s\n' "$SSH_COMMAND"
377:             printf 'AGENTSWEB_TUNNEL_URL=%s\n' "$SSH_TUNNEL_URL"
378:           } >> "$GITHUB_ENV"
379:           {
380:             printf 'AGENTSWEB_HOST=%s\n' "$SSH_HOST"
381:             printf 'AGENTSWEB_PORT=%s\n' "$SSH_PORT"
382:             printf 'AGENTSWEB_COMMAND=%s\n' "$SSH_COMMAND"
383:             printf 'AGENTSWEB_TUNNEL_URL=%s\n' "$SSH_TUNNEL_URL"
384:           } > "$SSH_DIR/access.env"
385:           printf 'host=%s\nport=%s\ncommand=%s\n' "$SSH_HOST" "$SSH_PORT" "$SSH_COMMAND" >> "$GITHUB_OUTPUT"
386:           ssh_verified=''
387:           for _ in {1..3}; do
388:             if ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \
389:               -o BatchMode=yes -o ConnectTimeout=10 -o ConnectionAttempts=1 \
390:               -i "$SSH_KEY" -p "$SSH_PORT" "runner@$SSH_HOST" true; then
391:               ssh_verified='true'
392:               break
393:             fi
394:             sleep 5
395:           done
396:           if [[ "$ssh_verified" != 'true' ]]; then
397:             echo 'AgentsWeb registered, but the SSH endpoint is not reachable.' >&2
398:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
399:             exit 1
400:           fi
401:           if [[ "$SSH_ONLY_REQUEST" == 'true' ]]; then
402:             body=$'🔐 **SSH-only debugging session is ready.**\n\n'
403:           else
404:             body=$'🔐 **Temporary AgentsWeb SSH session is ready.**\n\n'
405:           fi
406:           body+="Run: https://github.com/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}"$'\n'
407:           body+="SSH URL: \`${SSH_TUNNEL_URL}\`"$'\n'
408:           body+="Host: \`${SSH_HOST}:${SSH_PORT}\`"$'\n\n'
409:           body+=$'Connect while the job is active:\n\n```sh\n'
410:           body+="${SSH_COMMAND}"$'\n```\n\n'
411:           if [[ "$SSH_ONLY_REQUEST" == 'true' ]]; then
412:             body+=$'This run skips OpenCode and holds the runner for five hours for interactive debugging.'
413:           fi
414:           comment_response="$(jq -n --arg body "$body" '{body: $body}' \
415:             | gh api "repos/${TARGET_REPOSITORY}/issues/${TRIGGER_ISSUE_NUMBER}/comments" \
416:               --method POST --input -)"
417:           comment_id="$(jq -r '.id // empty' <<<"$comment_response")"
418:           [[ -n "$comment_id" ]]
419:           printf 'comment_id=%s\n' "$comment_id" >> "$GITHUB_OUTPUT"
420: 
421:           /usr/bin/time -p printf '## Worker SSH\n\n```sh\n%s\n```\n' "$SSH_COMMAND" >> "$GITHUB_STEP_SUMMARY"
